-- Setup completo do estado do painel Instagran (tabela + funcao + grants + import do backup)
begin;

create table if not exists public.painel_gilson_state (
  key text primary key,
  value jsonb,
  updated_at timestamptz not null default now()
);

alter table public.painel_gilson_state disable row level security;

grant select, insert, update on public.painel_gilson_state to anon, authenticated;

create or replace function public.merge_panel_state(patches jsonb)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as \$
declare
  k text;
  v jsonb;
begin
  for k, v in select * from jsonb_each(patches) loop
    if k = 'deleted' then
      insert into painel_gilson_state (key, value, updated_at)
      values ('deleted', v, now())
      on conflict (key) do update
      set value = (
            select coalesce(to_jsonb(array_agg(distinct e)), '[]'::jsonb)
            from jsonb_array_elements_text(
              coalesce(painel_gilson_state.value, '[]'::jsonb) || excluded.value
            ) e
          ),
          updated_at = now();
    else
      insert into painel_gilson_state (key, value, updated_at)
      values (k, v, now())
      on conflict (key) do update
      set value = coalesce(painel_gilson_state.value, '{}'::jsonb) || excluded.value,
          updated_at = now();
    end if;
  end loop;
end;
\$;

grant execute on function public.merge_panel_state(jsonb) to anon, authenticated;

