insert into public.painel_gilson_state (key, value, updated_at) values ($json$edits$json$, $json${"ac2":{"time":"12h","texto":"Você não precisa malhar 2 horas por dia para ter saúde.\n\n3 vezes por semana, 1 hora, no seu ritmo — já é suficiente para:\n\n✅ Dormir melhor\n✅ Reduzir o estresse\n✅ Ganhar disposição no dia a dia\n\nA ciência confirma. A gente te ajuda a colocar em prática.","title":"Dica de Saúde — 3x por semana já basta","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo visual: Informativo com elementos gráficos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Educativo\nObjetivo: Quebrar a objeção de \"não tenho tempo\" e \"academia é muito puxado\" — principal barreira do público feminino 30-40 anos para iniciar.\nFunil: Topo — educar e remover barreiras de entrada\nAção esperada: Salvamento do story e consideração de matrícula"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nQuebrar o mito de que academia exige muito tempo e esforço. Apresentar 3 benefícios reais e cotidianos de forma visual, limpa e fácil de consumir.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Estilo: Flat design minimalista — 3 ícones empilhados verticalmente\n• Ícone 1: Lua crescente — representa melhora do sono\n• Ícone 2: Folha ou planta — representa redução do estresse\n• Ícone 3: Sol ou raio de luz — representa disposição e energia\n• Cada ícone acompanhado de espaço para texto \n• Fundo limpo sem elementos distrativos\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — ícones e destaques\n• Teal #003f6b — acento nos ícones secundários\n• Branco #ffffff — área de texto\n\nESTILO VISUAL:\nFlat design moderno, linhas limpas, sem sombras excessivas. Ícones simples e universalmente reconhecíveis. Estética de infográfico de saúde e bem-estar.\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Sem pessoas ou corpos na ilustração\n• Sem elementos médicos (seringa, termômetro, etc.)\n• Sem cores além da paleta definida"}]},"ac3":{"time":"17h","texto":"27 anos cuidando da saúde de Turvo. 💛\n\nNa Planeta Corpo Club+ você treina com liberdade — qualquer dia, qualquer horário, todas as modalidades no mesmo plano.\n\nMusculação · Dança · Spinning · Funcional · Jump e muito mais.\n\nPromoção mês dos Namorados. Seu par romântico com até 50% off\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#PlanetaCorpo #Turvo #SaúdeDeVerdade #QualidadeDeVida","title":"Matrícula — 27 anos de história","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA direto"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Conversão / Chamada para Matrícula\nObjetivo: Apresentar a Planeta Corpo como academia confiável, completa e acessível para a comunidade de Turvo — usando os 27 anos de história como principal argumento de autoridade.\nFunil: Meio/Fundo — converter interesse em ação (contato ou visita)\nAção esperada: Clique no WhatsApp, visita à academia ou DM"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost institucional que comunica tradição, completude e acessibilidade. O número \"27 anos\" é o âncora principal — transmite confiança em uma cidade pequena onde reputação vale muito.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout dividido: parte superior com logo e \"27 anos\", parte inferior com lista de modalidades\n• Fundo escuro com textura sutil (grade fina ou ruído leve)\n• Silhuetas minimalistas de 4-5 modalidades diferentes ao redor do logo\n• Silhuetas em laranja (#e63900) e teal (#003f6b) alternando\n• Espaço central limpo para o logo Planeta Corpo\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — \"27 anos\" e CTA\n• Teal #003f6b — separadores e acentos\n• Branco #ffffff — texto e logo\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — topo, centralizado\n2. \"27 ANOS\" em laranja — maior elemento tipográfico\n3. Lista de modalidades — meio, fonte média\n4. Preço e contato — base, fonte menor mas visível\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Sem texto na imagem gerada pelo ChatGPT\n• Silhuetas apenas — sem rostos ou pessoas identificáveis\n• Sem elementos de academia genérica ou concorrente"}]},"ac4":{"time":"20h","texto":"Tem gente que acha que academia é coisa de quem já é fitness.\n\nA gente pensa diferente. 🧡\n\nA Planeta Corpo existe para quem quer começar, para quem parou e quer voltar, e para quem só precisa de um lugar gostoso de treinar.\n\nDesde 1998 sendo esse lugar pra Turvo. 🧡","title":"Humanização — Academia é pra todo mundo","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, minimal — foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização da Marca\nObjetivo: Quebrar barreiras psicológicas de quem nunca foi à academia ou parou. Posicionar a Planeta Corpo como lugar acolhedor, sem julgamentos, para pessoas reais.\nFunil: Topo — criar conexão emocional com não-alunos\nAção esperada: Compartilhamento (\"isso é pra mim\") e lembrança de marca"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDesfazer o mito de que academia é lugar de pessoas já em forma. Tom de conversa sincera, como se fosse uma mensagem direta do professor Gilson para alguém que tem vontade mas tem medo de começar.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia como fundo em anexo\n• Overlay mínimo — a foto deve respirar e aparecer com clareza\n• Sem elementos gráficos pesados — o espaço real comunica mais que qualquer arte\n• Iluminação: quente e acolhedora — se a foto tiver isso, não mexa\n• Sem pessoas na foto — o espaço vazio convida o espectador a se imaginar ali\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15% opacidade)\n• Laranja #e63900 — emoji e palavra-chave ocasional\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. A foto real vale mais que qualquer arte produzida nesse contexto. Autenticidade é o diferencial desse story.\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Não adicione filtros pesados na foto\n• Sem emojis de músculo, fogo ou performance\n• Use apenas 🧡 como emoji — combina com o laranja da marca"}]},"ac5":{"time":"08h","texto":"Parou de treinar e ficou com aquela sensação de \"será que ainda dá tempo\"?\n\nDá sim. 🧡\n\nSeu corpo não esquece o que você já construiu — ele só está esperando você voltar.\n\nSem cobrança, sem julgamento. No seu ritmo, como sempre foi aqui.\n\nBora retomar essa semana?","title":"Dica de Saúde — Voltar não é fracasso","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Acolhedor, motivacional sem pressão"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde\nObjetivo: Reconectar com alunas que pararam de treinar, removendo a culpa e convidando ao retorno sem julgamento — atacando o gargalo de alunos inativos (108 de 215).\nFunil: Meio — reativação de base existente\nAção esperada: Comentário, DM ou retorno à academia na semana"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nSimbolizar \"retomada\" e \"novo começo\" sem culpa — uma trilha ou caminho que leva a um sol nascente, transmitindo acolhimento e recomeço tranquilo.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Ilustração flat design de uma trilha de pegadas levando a um sol nascente\n• Estilo minimalista, sem pessoas\n• Espaço inferior para foto real da academia (Academia24.jpg) como camada de fundo\n• Espaço central/superior para o texto\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo\n• Laranja #e63900 — sol e destaques\n• Teal #003f6b — acentos\n• Branco #ffffff — texto\n\nESTILO VISUAL:\nAcolhedor, sem pressa, tom de \"estamos esperando você\" — nada de urgência ou cobrança.\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Sem elementos de cobrança ou comparação (sem \"última chance\", sem números de peso)\n• Foto real da academia deve ser incluída como camada de fundo"}]},"ac6":{"time":"12h","texto":"Aqui não tem ranking de quem levanta mais peso. 😊\n\nTem gente que vem pra suar, gente que vem pra desligar a cabeça, gente que vem só pra não ficar em casa.\n\nTodo motivo é motivo válido.\n\nA Planeta Corpo é desse jeito desde 1998 — um espaço pra você ser quem você é. 🧡","title":"Humanização — Cada um no seu ritmo","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, minimal — foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização da Marca\nObjetivo: Reforçar que a academia é um espaço sem comparação ou julgamento, acolhendo diferentes motivações — ajuda a reduzir a evasão ao tornar o ambiente psicologicamente seguro.\nFunil: Topo/Meio — fortalecer vínculo com alunos atuais e atrair indecisos\nAção esperada: Identificação, compartilhamento, comentário com emoji"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nFoto real do espaço da academia, tranquila, sem pessoas, transmitindo um ambiente sem pressão e sem comparação — o texto reforça essa mensagem.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia (Academia23.jpg do Drive) como fundo\n• Overlay mínimo preto (#1a1a1a) — apenas para o texto aparecer\n• Sem elementos gráficos adicionais — autenticidade é o ponto forte\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji 🧡\n• Branco #ffffff — texto\n\nESTILO VISUAL:\nTom leve, humano e direto. Foto real comunica mais que arte produzida.\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Não aplicar filtros pesados na foto\n• Sem elementos gráficos além do texto e logo\n• Use apenas emojis 😊🧡"}]},"ac7":{"time":"17h","texto":"Treinar 1x ou 5x por semana. De manhã, de tarde ou de noite. Você escolhe. 🧡\n\nNa Planeta Corpo Club+ é assim: um plano só, liberdade total — Musculação, Dança, Spinning, Funcional, Jump, HIIT e aulas com o Prof. Wellinton.\n\nR$ 209/mês. Sem fidelidade chata, sem letra miúda.\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#PlanetaCorpo #Turvo #SaúdeDeVerdade #QualidadeDeVida","title":"Convite à Matrícula — Treine sem compromisso engessado","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA direto"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Convite à Matrícula\nObjetivo: Comunicar a liberdade de horário e a amplitude de modalidades como diferenciais para atrair novos alunos — destacando o plano único sem fidelidade.\nFunil: Meio/Fundo — converter interesse em contato\nAção esperada: Clique no WhatsApp, DM ou visita à academia"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nComunicar \"liberdade de horário\" como principal diferencial — ícones representando manhã, tarde, noite e dias da semana, com o logo como elemento central.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo preto (#1a1a1a) com grade fina sutil\n• Ícones minimalistas de relógio, calendário, sol e lua dispostos ao redor do espaço central\n• Espaço central limpo para o logo Planeta Corpo\n• Ícones em laranja (#e63900) e teal (#003f6b) alternando\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo\n• Laranja #e63900 — destaque principal e ícones\n• Teal #003f6b — acentos\n• Branco #ffffff — texto\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — centro\n2. Ícones de liberdade de horário — ao redor\n3. Lista de modalidades — abaixo\n4. Preço e contato — base\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Apenas ícones minimalistas — sem pessoas"}]},"ac9":{"time":"08h","texto":"Quarta-feira. Aquele dia que a motivação costuma cair. 💛\n\nE mesmo assim, ela veio treinar.\n\nNão porque sentiu vontade — porque sabia que ia se sentir melhor depois. E sentiu.\n\nQuer chegar lá também? Manda mensagem! 👇\n📲 (42) 99922-2857\n\n#fitness #academia #musculação #saudeebemestar #vidafitness #academiaparana #treinodiario #qualidadevida #mulheresativa #saudeemdia #treinofeminino #vidaativa #emagrecimento #treinofuncional #hiit #jump #musculacaofeminina #bemestarsaude #treinando #exerciciofisico #academiaturvoPR #turvoPR #planetacorpo #planetacorpoclubmais #academialocal #treinoturvo #guarapuava #guarapuavafit #interiorpr #cidadeinterior","title":"Prova Social — Meio de semana, foco mantido","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: manter elementos entre 150px das bordas superior e inferior\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social\nObjetivo: Validar o esforço de superar a queda natural de motivação no meio da semana — reforçar que o resultado emocional pós-treino compensa a resistência inicial.\nFunil: Topo — identificação emocional com quem hesita em treinar no meio de semana\nAção esperada: Comentário de identificação, salvamento, DM"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nRetratar o momento de superação da resistência mental de quarta-feira — o \"não queria vir, mas vim\" que tantas pessoas sentem. Expressão de alívio e satisfação pós-decisão.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: mulher de 30-40 anos com expressão de leve cansaço transformando-se em satisfação\n• Ambiente: imagem da academia em anexo, iluminação natural quente\n• Expressão: alívio genuíno, não esforço extremo\n• Ângulo: plano médio, câmera na altura dos olhos\n• Profundidade de campo: rasa, foco no rosto\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — acento secundário\n• Preto #1a1a1a — fundo e overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista, luz natural quente, autenticidade emocional genuína — sem produção excessiva."}]},"gy2":{"time":"10h","texto":"🏆 Imagine seus alunos COMPETINDO para treinar mais.\n\nCom o GympulsePro você transforma cada treino em pontos, rankings e conquistas.\n\n✅ Monitor ao vivo\n✅ Rankings por categoria\n✅ Engajamento real\n✅ Retenção comprovada\n\nSua academia merece isso. 🚀\n\n#GympulsePro #GamificaçãoFitness #TechFitness #RetençãoDeAlunos","title":"Funcionalidade — Monitor ao vivo","format":"Post","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem: 80px nas bordas\nEstilo: SaaS premium, tech, B2B"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Funcionalidade do Produto\nObjetivo: Mostrar o monitor ao vivo como diferencial competitivo do GympulsePro — a funcionalidade mais visual e impactante do sistema. Usar screenshot real para credibilidade máxima.\nFunil: Meio — consideração e avaliação (gestor já consciente do problema de retenção)\nAção esperada: Clique no link da bio, salvamento ou DM solicitando demo"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nO screenshot real do monitor GympulsePro é a prova mais poderosa. O gestor precisa VER o produto funcionando em outra academia real. Todo o design serve para destacar esse screenshot.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: screenshot do monitor ocupa 60% do espaço central do post\n• Frame/moldura: borda amarela (#f5c200) ao redor do screenshot — destaca e dá acabamento premium\n• Fundo: preto (#0d0d0d) com elementos de interface tech em cinza escuro (#1c1c1c)\n• Elementos decorativos ao redor: ícones de badge, troféu e pontos em amarelo (#f5c200)\n• Logo GympulsePro no topo centralizado\n• Lista de 4 benefícios na parte inferior\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo total\n• Amarelo #f5c200 — frame do screenshot, ícones e destaques\n• Cinza escuro #1c1c1c — elementos de interface decorativos\n• Branco #ffffff — texto dos benefícios\n\nHIERARQUIA VISUAL:\n1. Screenshot real com frame amarelo — elemento hero\n2. Logo GympulsePro no topo\n3. 4 benefícios com ✅ amarelo na base\n4. CTA implícito na legenda\n\n"}]},"gy5":{"time":"10h","texto":"🎁 Seus alunos treinam, ganham pontos... e depois?\n\nNo GympulsePro, cada treino vira Fitcoins — moeda interna que o aluno troca por recompensas reais: squeeze, copo térmico, camiseta, açaí com whey.\n\nEngajamento que não fica só na tela. Vira retenção.\n\nQuer ativar isso na sua academia? 👇\n\n#GympulsePro #GamificaçãoFitness #TechFitness #RetençãoDeAlunos","title":"Funcionalidade — Recompensas que viram hábito","format":"Post","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem: 80px nas bordas\nEstilo: SaaS premium, tech, B2B"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Funcionalidade do Produto\nObjetivo: Apresentar o sistema de Fitcoins como ferramenta de retenção — atacando o gargalo de 157 fitcoins ganhos vs 0 resgatados (recompensas não utilizadas).\nFunil: Meio — consideração, mostrando funcionalidade ainda pouco explorada\nAção esperada: DM perguntando sobre o sistema de recompensas"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMostrar a \"vitrine\" de recompensas reais que os Fitcoins desbloqueiam — o screenshot real do GympulsePro como prova de que o sistema existe e funciona.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: screenshot do GympulsePro (Drive) com frame amarelo (#f5c200) central\n• Ícones de recompensas (squeeze, camiseta, copo térmico, medalha) em estilo flat dispostos como vitrine ao redor do screenshot\n• Fundo preto (#0d0d0d) com elementos de interface em cinza escuro (#1c1c1c)\n• Logo GympulsePro no topo\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo total\n• Amarelo #f5c200 — frame e ícones\n• Cinza escuro #1c1c1c — elementos secundários\n• Branco #ffffff — texto\n\nHIERARQUIA VISUAL:\n1. Screenshot real com frame amarelo — elemento hero\n2. Ícones de recompensas ao redor\n3. Logo GympulsePro no topo\n4. Texto explicativo na base\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Screenshot real do Drive obrigatório\n• Sem cores além da paleta oficial"}]},"gy6":{"time":"18h","texto":"💡 Tem academia que começou só pra \"ver como funciona\"...\n\n...e hoje já tem mais de 100 aulas registradas no GympulsePro. 📈\n\nQuando os alunos veem o ranking em tempo real, eles voltam — e voltam com mais frequência.\n\nSua academia também pode testar gratuitamente.\n\nManda mensagem e agenda sua demo! 👊","title":"Demo — De curiosidade a hábito","format":"Story","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Dashboard premium, dado de crescimento"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Demo / Prova Social\nObjetivo: Usar o caso real da Academia Life (trial ativo, 108 aulas registradas) como prova de que o produto gera engajamento mesmo em fase de teste — incentivando outras academias a testarem.\nFunil: Fundo — conversão direta para demo\nAção esperada: DM solicitando demo gratuita"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nGráfico de crescimento ascendente como elemento visual central, com o screenshot real do monitor como prova abaixo — narrativa de \"começou pequeno, virou hábito\".\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo preto (#0d0d0d) com gráfico de crescimento ascendente estilizado em amarelo (#f5c200)\n• Grid digital sutil em cinza escuro (#1c1c1c)\n• Espaço inferior para o screenshot real do monitor Academia Life (Drive), com borda amarela\n• Espaço superior para texto\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo principal\n• Amarelo #f5c200 — gráfico e destaques\n• Cinza escuro #1c1c1c — grid e elementos secundários\n• Branco #ffffff — texto de apoio\n\nESTILO VISUAL:\nB2B tech, confiável e premium — sensação de dado real de painel de gestão.\n\nRESTRIÇÕES OBRIGATÓRIAS:\n• Screenshot real do Drive obrigatório\n• Sem ícones de fitness genéricos"}]},"gy8":{"time":"18h","texto":"Cada treino vira Fitcoins. Cada Fitcoin pode ser trocado por prêmios reais. 🪙\n\nSqueeze, copo térmico, camiseta, suplementos — o aluno enxerga valor tangível no esforço que faz todos os dias.\n\nIsso é retenção sendo construída na prática.\n\nQuer ver isso funcionando na sua academia? 🎮\nDemo gratuita — manda mensagem! 👇\n","title":"Funcionalidade — Fitcoins e recompensas reais","format":"Story","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Funcionalidade com apelo visual de recompensa"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Funcionalidade do Produto\nObjetivo: Demonstrar o sistema de Fitcoins como ponte tangível entre esforço físico e recompensa real — diferencial competitivo concreto do GympulsePro.\nFunil: Meio — consideração e diferenciação de concorrentes\nAção esperada: Salvamento, DM solicitando demo"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nVisualizar a jornada \"treino → pontos → recompensa real\" de forma simples e atrativa, mostrando produtos reais que podem ser trocados (squeeze, camiseta, copo térmico).\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: preto (#0d0d0d) com elementos tech sutis\n• Elemento central: ícone de moeda estilizada (Fitcoin) com efeito de brilho em amarelo (#f5c200)\n• Elementos ao redor: pequenos ícones simples de squeeze, camiseta e copo térmico\n• Seta ou fluxo visual conectando \"treino → moeda → produto\"\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo principal\n• Amarelo #f5c200 — moeda e destaques\n• Cinza escuro #1c1c1c — ícones de produtos\n• Branco #ffffff — texto explicativo\n\nESTILO VISUAL:\nDark tech premium, visual de \"jornada de recompensa\" clara e motivadora."}]},"so2":{"time":"11h30","texto":"Venha experimentar os sabores Juninos! 🍦☀️\n\nSabores que trazem nostalgia.\n\nVenha nos visitar em Turvo/PR!\n\n#SorvetesGuri #Turvo #lojadefábrical #MomentoGuri #festajunina","title":"Construção de Marca — Foto produto","format":"Post","secoes":[{"cor":"#f5c800","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem: 80px nas bordas\nEstilo: Food photography — produto como protagonista"},{"cor":"#00b4d8","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Construção de Marca / Brand Awareness\nObjetivo: Consolidar a identidade visual da Sorveteria Guri no feed — post permanente que comunica qualidade e alegria do produto. Não é promocional, é de posicionamento.\nFunil: Topo — reconhecimento e desejo\nAção esperada: Curtida, salvamento e visita futura"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost de produto limpo e apetitoso. O sorvete deve ser o protagonista absoluto. Menos é mais — design serve ao produto, não compete com ele.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Ângulo: flat lay (vista de cima 90°) ou 3/4 levemente elevado\n• Produto: a imagem em anexo em destaque central, bem iluminado\n• Superfície: azul turquesa (#00b4d8) ou mármore branco com toques azuis\n• Elementos decorativos: relacionado à festa junina\n• Luz: natural e suave, sem sombras duras\n\nPALETA OBRIGATÓRIA:\n• Azul turquesa #00b4d8 — fundo/superfície\n• Amarelo #f5c800 — elementos decorativos\n• Azul escuro #003f6b — texto e logo\n• Branco #ffffff — espaço limpo ao redor do produto\n\nESTILO VISUAL:\nFood photography profissional. Apetitoso, fresco e alegre. A imagem deve dar vontade de comer imediatamente.\n\n"}]},"so5":{"time":"09h","texto":"🍦 Bom dia, Turvo!\n\nTerça-feira também merece um sorvetinho, né?\n\nHoje em destaque: CHURROS 😍\n\nPassa lá na loja!","title":"Produto do Dia — Terça tem sabor especial","format":"Story","secoes":[{"cor":"#f5c800","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Festivo, colorido, energético"},{"cor":"#00b4d8","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Produto do Dia / Divulgação\nObjetivo: Manter o hábito diário de comunicação do sabor do dia, reforçando recorrência e gerando visita física no mesmo dia.\nFunil: Fundo — conversão imediata\nAção esperada: Visita à sorveteria ainda na terça"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nStory diário recorrente, mesmo padrão visual de segunda-feira para criar reconhecimento — mascote Guri como comunicador, fundo festivo em degradê.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: degradê diagonal de azul escuro (#003f6b) para azul turquesa (#00b4d8)\n• Elementos decorativos: confetes e formas geométricas em amarelo (#f5c800) e branco\n• Mascote Guri (Drive) posicionado à direita, ocupando 60% da altura\n• Caixa amarela (#f5c800) com borda arredondada reservada para o nome do sabor\n\nPALETA OBRIGATÓRIA:\n• Azul escuro #003f6b — fundo principal\n• Azul turquesa #00b4d8 — degradê\n• Amarelo #f5c800 — caixa do sabor e confetes\n• Branco #ffffff — texto e logo\n\nESTILO VISUAL:\nFestivo e alegre, alta energia, cores saturadas e harmônicas.\n\n"}]},"ac10":{"time":"12h","texto":"Sua postura no trabalho também é treino. 🧘‍♀️\n\n3 ajustes simples que fazem diferença:\n\n✅ Ombros relaxados, não levantados\n✅ Tela do computador na altura dos olhos\n✅ Levante e alongue a cada 1 hora\n\nPequenos ajustes, grande alívio nas costas no fim do dia.\n\nComenta aqui: qual desses você vai aplicar hoje? 👇\n","title":"Dica de Saúde — Postura no dia a dia","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Informativo com elemento gráfico simples"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Educativo\nObjetivo: Conectar saúde física ao cotidiano de trabalho do público-alvo (muitas trabalham sentadas), reforçando relevância da academia além do horário de treino.\nFunil: Topo — educação aplicável ao dia a dia\nAção esperada: Resposta ao story, salvamento"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDica prática sobre postura no ambiente de trabalho, com ilustração simples de figura humana estilizada mostrando postura correta vs incorreta.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Ilustração flat design de silhueta sentada com postura correta destacada\n• Setas ou indicadores sutis nos pontos-chave (ombros, tela, coluna)\n• Estilo minimalista, sem realismo fotográfico\n• Espaço amplo para texto ser adicionado no Canva\n\nPALETA OBRIGATÓRIA:\n• Azul escuro #003f6b — silhueta principal\n• Laranja #e63900 — indicadores e pontos de atenção\n• Preto #1a1a1a — fundo\n• Branco #ffffff — área de texto\n\nESTILO VISUAL:\nFlat design educativo, limpo, fácil de entender em poucos segundos."}]},"ac11":{"time":"17h","texto":"Por que pagar várias mensalidades quando você pode ter tudo em uma? 💛\n\nNa Planeta Corpo, um único plano te dá acesso a:\n\n✅ Musculação\n✅ Dança\n✅ Ginástica\n✅ Spinning\n✅ Funcional\n✅ Jump\n✅ Lutas\n\nSem letra miúda. Sem surpresa na fatura.\n\nAula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n #saudeebemestar #qualidadevida #saudeemdia #treinofuncional #academiaturvoPR #planetacorpoclubmais ","title":"Matrícula — Todas as modalidades em um plano","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA direto"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Conversão / Chamada para Matrícula\nObjetivo: Destacar o custo-benefício de um único plano com múltiplas modalidades — argumento racional/financeiro complementando os argumentos emocionais de outros posts.\nFunil: Meio/Fundo — converter interesse em contato\nAção esperada: Clique no link da bio, mensagem no WhatsApp"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost de comparação implícita — \"várias mensalidades vs uma só\" — destacando economia e simplicidade como diferencial competitivo real.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: logo no topo, lista as modalidades com ícones simples no meio, CTA na base\n• Fundo escuro com textura sutil\n• Ícones minimalistas para cada modalidade (peso, sapatilha de dança, bike, corda, prancha)\n• Espaço limpo e organizado\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — ícones e acentos\n• Branco #ffffff — texto e logo\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — topo\n2. Frase de abertura sobre economia — destaque médio\n3. Os ícones de modalidades em grid\n4. CTA de aula experimental — base, cor laranja"}]},"ac12":{"time":"20h","texto":"Cada aula coletiva tem alguém cuidando de cada detalhe pra você ter o melhor treino possível. 🧡\n\nProf. Wellinton é só um exemplo de quem faz parte dessa equipe que está aqui por você, todos os dias.\n\nObrigado por confiar na gente. 💛\n\nMarque alguém que precisa conhecer esse cuidado 👇\n\n","title":"Bastidores — Professor Wellinton em ação","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização / Bastidores\nObjetivo: Dar rosto e nome à equipe (Prof. Wellinton), reforçando que o acompanhamento é pessoal e dedicado — não anônimo ou genérico.\nFunil: Meio — fidelização e reforço de marca\nAção esperada: Marcação de amigos, reconhecimento do professor pelos alunos"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nHumanizar a equipe através de menção nominal a um professor específico, reforçando que cada aula coletiva tem cuidado e atenção dedicados — não é apenas \"mais uma aula\".\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia com foco no espaço de aulas coletivas\n• Overlay mínimo — autenticidade prevalece\n• Iluminação quente, se a foto tiver isso, preservar\n• Sem necessidade de rosto visível — o espaço já comunica cuidado\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji e detalhe pontual\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. Tom de reconhecimento sincero à equipe — humaniza a marca através de nome próprio."}]},"ac14":{"time":"12h","texto":"Você sabe quem está te orientando no seu treino? 🎓\n\nNa Planeta Corpo, 100% da nossa equipe tem registro no CREF.\n\nNão é qualquer pessoa de roupa de academia te dando instrução — é profissional formado e registrado, comprometido com a sua segurança e resultado.\n\nIsso faz toda diferença na sua saúde a longo prazo.\n\nComenta aqui: você sabia que isso é importante? 👇\n\n","title":"Diferencial — Equipe 100% CREF","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Institucional, autoridade profissional"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Diferencial Competitivo / Autoridade\nObjetivo: Destacar o diferencial de equipe 100% CREF de forma educativa, gerando confiança e diferenciação indireta frente a concorrentes que podem não ter essa qualificação completa.\nFunil: Meio — construção de confiança e autoridade\nAção esperada: Comentário, salvamento, reconhecimento de valor"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nComunicar o diferencial de equipe profissional registrada de forma educativa e não-agressiva, gerando reflexão sobre a importância da qualificação profissional em academias.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Elemento central: ícone estilizado de crachá/certificado com símbolo de check\n• Fundo: preto (#1a1a1a) com textura sutil\n• Elementos secundários: pequenos ícones representando cuidado profissional\n• Espaço para texto destacando \"100% CREF\"\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque do número \"100%\"\n• Azul escuro #003f6b — ícones e elementos secundários\n• Preto #1a1a1a — fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nInstitucional e confiável, tom educativo sem soar arrogante ou comparativo direto."}]},"ac16":{"time":"20h","texto":"Fim de mais um dia de muito trabalho por aqui. 🧡\n\nCada equipamento organizado, cada espaço cuidado — é assim que a gente recebe você todos os dias.\n\nObrigado por fazer parte dessa rotina com a gente. 💛\n\nMarque alguém que também faz parte dessa comunidade 👇\n\n#academia #musculação #turvoPR  #planetacorpoclubmais #academialocal ","title":"Bastidores — Cuidado com cada detalhe","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização / Bastidores\nObjetivo: Mostrar o cuidado por trás do espaço físico — reforça percepção de profissionalismo e carinho com os detalhes.\nFunil: Meio — fidelização e reforço de marca para alunos atuais\nAção esperada: Marcação de amigos, resposta emocional ao story"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nFechamento do dia mostrando o cuidado da equipe com o espaço — agradecimento sincero à comunidade.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia ao fim do expediente\n• Overlay mínimo — autenticidade prevalece sobre produção\n• Iluminação quente de fim de dia\n• Sem pessoas — o espaço cuidado fala por si\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji e detalhe pontual\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. Tom de gratidão sincera ao fim do dia."}]},"ac17":{"time":"08h","texto":"Sexta-feira. Semana completa de treino. 💪\n\nEla não faltou nenhum dia — não porque é fácil, mas porque decidiu que merece se cuidar.\n\nEsse é o tipo de compromisso que transforma rotina em resultado de verdade.\n\nQuer começar sua própria semana completa? Manda mensagem! 👇\n📲 (42) 99922-2857","title":"Prova Social — Sexta-feira de conquista","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social\nObjetivo: Celebrar a conquista de completar a semana de treinos, gerando identificação e aspiração em quem ainda não tem essa consistência.\nFunil: Topo — identificação emocional com aspiração de consistência\nAção esperada: Comentário, salvamento, DM"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nCelebração discreta de fim de semana de treino completo — sensação de orgulho genuíno e merecido, sem exagero ou comemoração espalhafatosa.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: mulher de 30-40 anos com expressão de leve orgulho e satisfação\n• Ambiente: academia pequena, luz de fim de tarde de sexta-feira\n• Expressão: sorriso genuíno, tranquilo\n• Ângulo: plano médio, câmera na altura dos olhos\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — acento secundário\n• Preto #1a1a1a — fundo e overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista, luz quente de fim de tarde, sensação de conquista pessoal genuína."}]},"ac18":{"time":"12h","texto":"Você merece treinar em paz. 🛡️\n\nNa Planeta Corpo, não toleramos nenhum tipo de assédio ou desrespeito com nossas alunas. Esse é um compromisso da nossa equipe, todos os dias.\n\nVocê vem aqui pra cuidar de você — e a gente cuida pra que isso aconteça em um ambiente seguro e acolhedor.\n\nComenta aqui: isso faz diferença na sua escolha de academia? 👇\n","title":"Diferencial — Ambiente seguro para mulheres","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Institucional, tom sério e acolhedor"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Diferencial Competitivo / Posicionamento de Valor\nObjetivo: Comunicar de forma direta e respeitosa o compromisso com a segurança das mulheres — tema extremamente relevante para o público-alvo de 30-40 anos.\nFunil: Topo/Meio — construção de confiança e valores compartilhados\nAção esperada: Comentário, identificação com os valores da marca, compartilhamento"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nComunicar o compromisso com ambiente seguro de forma séria, respeitosa e acolhedora — sem soar como propaganda vazia, mas como valor genuíno da marca.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Elemento central: ícone estilizado de escudo ou símbolo de proteção, suave e não agressivo\n• Fundo: tons quentes e acolhedores, não ameaçadores\n• Elementos secundários: detalhes sutis transmitindo cuidado\n\nPALETA OBRIGATÓRIA:\n• Azul escuro #003f6b — ícone central de proteção\n• Laranja #e63900 — pequenos acentos\n• Preto #1a1a1a — fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nSério mas acolhedor, nunca alarmista — transmite segurança através de tom calmo e confiante."}]},"ac19":{"time":"17h","texto":"Sexta-feira é um ótimo dia para tomar uma decisão por você. 💛\n\nQue tal aproveitar o fim de semana para conhecer a Planeta Corpo e dar o primeiro passo na sua nova rotina de saúde?\n\n✅ Mais de 27 anos cuidando de Turvo\n✅ Equipe 100% CREF\n✅ Estrutura completa e moderna\n✅ Desconto Especial para Casais\n\nAula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#academia #turvoPR #saúde\n","title":"Matrícula — Comece o fim de semana decidindo por você","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA de fim de semana"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Conversão / Chamada para Matrícula\nObjetivo: Aproveitar o gancho emocional de sexta-feira (início de decisões novas) para gerar contato antes do fim de semana, consolidando 3 diferenciais principais de forma resumida.\nFunil: Meio/Fundo — converter interesse em contato\nAção esperada: Clique no link da bio, mensagem no WhatsApp"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost de fechamento de semana convidando à ação antes do fim de semana, resumindo os 3 principais diferenciais da academia de forma direta e acessível.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: logo no topo, 3 diferenciais com ícones no meio, CTA na base\n• Fundo escuro com textura sutil\n• Ícones minimalistas para cada diferencial (anos de história, CREF, estrutura)\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — ícones e acentos\n• Branco #ffffff — texto e logo\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — topo\n2. Frase de convite sexta-feira — destaque médio\n3. 3 diferenciais com ícones em lista\n4. CTA de aula experimental — base"}]},"ac20":{"time":"20h","texto":"Sexta-feira movimentada por aqui! 🧡\n\nAdoramos ver a academia cheia de gente cuidando da própria saúde antes do fim de semana.\n\nObrigado por fazer parte dessa comunidade. 💛\n\nBom fim de semana pra você! Marque alguém que precisa começar essa rotina também 👇\n","title":"Bastidores — Sexta de muito movimento","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização / Bastidores\nObjetivo: Mostrar movimento e vitalidade da academia em sexta-feira, reforçando senso de comunidade ativa antes do fim de semana.\nFunil: Meio — fidelização e prova social indireta de movimento\nAção esperada: Marcação de amigos, desejo de boa semana compartilhado"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nFechamento de semana mostrando vitalidade e movimento da academia, com tom de despedida calorosa para o fim de semana.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia com sensação de movimento\n• Overlay mínimo — autenticidade prevalece\n• Iluminação quente de fim de tarde de sexta\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji e detalhe pontual\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. Tom caloroso de despedida de semana."}]},"ac21":{"time":"10h","texto":"Sábado também é dia de se cuidar. ☀️\n\nTreinar no fim de semana é a prova de que sua saúde não tira folga — porque você decidiu que ela é prioridade todos os dias.\n\nBom treino, bom sábado! 💛\n\nComenta aqui: você é do time que treina no fim de semana? 👇\n\n#academia #musculação #turvoPR  #planetacorpoclubmais ","title":"Sábado — Motivação de fim de semana","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Motivacional leve, tom de fim de semana"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Motivação de Fim de Semana\nObjetivo: Manter presença de marca no sábado com volume reduzido, reconhecendo o menor movimento mas mantendo engajamento com quem treina no fim de semana.\nFunil: Topo — engajamento leve, manutenção de presença\nAção esperada: Comentário, curtida, identificação com o tema"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nTom leve e descontraído de sábado, celebrando quem mantém a rotina mesmo no fim de semana, sem pressão ou urgência.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia com luz de sábado, mais tranquila\n• Atmosfera relaxada, menos movimento que dias de semana\n• Tom visual mais leve e solar\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e elementos solares\n• Azul escuro #003f6b — acento secundário\n• Preto #1a1a1a — fundo e overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nLeve, solar, despreocupado — tom de fim de semana sem perder a identidade da marca."}]},"ac22":{"time":"16h","texto":"Aproveitando o sábado pra recarregar as energias. ☀️💛\n\nEsse é o tipo de cuidado que faz toda diferença na segunda-feira.\n\nBom fim de semana, Turvo! 🧡","title":"Sábado — Comunidade que se cuida junto","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Leve, relaxado, fim de semana"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Relacionamento / Fim de Semana\nObjetivo: Encerrar a presença de sábado com tom leve de comunidade e cuidado pessoal, preparando terreno emocional positivo para a segunda-feira.\nFunil: Topo — manutenção de vínculo emocional\nAção esperada: Resposta ao story, sensação de pertencimento"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nStory de encerramento de sábado com tom de recarga de energia e preparação positiva para a semana que se inicia.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia com luz suave de tarde de sábado\n• Atmosfera tranquila e relaxada\n• Sensação de pausa reparadora\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — emoji e detalhe pontual\n• Azul escuro #003f6b — acento secundário\n• Preto #1a1a1a — overlay mínimo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nLeve, contemplativo, tom de pausa positiva de fim de semana."}]},"ac23":{"time":"08h","texto":"Começando a semana com o pé direito! 💛\n\nSegunda-feira não precisa ser sinônimo de cansaço — pode ser o dia que você escolhe cuidar de você antes de tudo.\n\nNossas alunas já sabem: treinar de manhã muda o resto do dia.\n\nBora começar essa semana com energia? Manda mensagem! 👇\n📲 (42) 99922-2857\n","title":"Prova Social — Segunda-feira começando com energia","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: manter elementos entre 150px das bordas superior e inferior\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social / Motivação de Início de Semana\nObjetivo: Aproveitar o gancho emocional de segunda-feira para reforçar que treinar pela manhã muda a disposição do dia, gerando identificação com quem busca uma rotina mais saudável.\nFunil: Topo — despertar interesse e criar conexão emocional\nAção esperada: Comentário, compartilhamento ou DM solicitando informações"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMulher comum, em momento de disposição matinal — clima de \"começo de semana com energia\", não de esforço extremo.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: mulher sorrindo de forma natural, roupas simples de treino\n• Expressão: disposição e energia matinal, leve animação\n• Ambiente: academia pequena e acolhedora, luz da manhã entrando\n• Ângulo: plano médio, câmera na altura dos olhos\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista com luz natural quente de manhã. Autenticidade acima de produção excessiva."}]},"ac24":{"time":"12h","texto":"Você bebe água o suficiente hoje? 💧\n\nA hidratação correta antes, durante e depois do treino:\n\n✅ Melhora o rendimento muscular\n✅ Reduz risco de cãibras e lesões\n✅ Acelera a recuperação\n\nMeta simples: 2 litros de água por dia, mais um pouco no dia de treino.\n\nPequenos hábitos, grandes resultados. 💛\n","title":"Dica de Saúde — Hidratação também é treino","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Conteúdo Educativo\nObjetivo: Entregar valor prático e simples sobre hidratação, posicionando a marca como referência de cuidado completo (não só treino, mas hábitos saudáveis).\nFunil: Topo — autoridade e construção de confiança\nAção esperada: Salvamento do story, aplicação prática da dica"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDica prática e objetiva sobre hidratação, com linguagem simples e meta concreta (2 litros/dia) — fácil de lembrar e aplicar.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: foto da academia com overlay translúcido\n• Elemento central: ícone estilizado de gota d'água ou garrafa, em destaque\n• Lista de 3 benefícios com checkmarks em laranja\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — ícone e checkmarks\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nEducativo, limpo, fácil leitura rápida típica de story."}]},"ac25":{"time":"17h","texto":"Segunda-feira é a véspera perfeita pra começar algo novo. 💛\n\nQue tal aproveitar essa semana pra dar o primeiro passo na sua nova rotina de saúde?\n\n✅ Mais de 27 anos cuidando de Turvo\n✅ Equipe 100% CREF\n✅ Estrutura completa e moderna\n✅ Promoção para casais, até 50% off\n\nAula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#musculaçãoa #emagrecimento #academiaturvoPR #turvoPR #planetacorpoclubmais ","title":"Matrícula — Comece a semana decidindo por você","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA de início de semana"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Conversão / Chamada para Matrícula\nObjetivo: Aproveitar o gancho emocional de segunda-feira (início de decisões novas) para gerar contato no começo da semana, consolidando os 3 principais diferenciais.\nFunil: Meio/Fundo — converter interesse em contato\nAção esperada: Clique no link da bio, mensagem no WhatsApp"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost de abertura de semana convidando à ação, resumindo os 3 principais diferenciais da academia de forma direta e acessível — gancho de \"começar de novo\" típico de segunda-feira.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: logo no topo, 3 diferenciais com ícones no meio, CTA na base\n• Fundo escuro com textura sutil\n• Ícones minimalistas para cada diferencial\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — ícones e acentos\n• Branco #ffffff — texto e logo\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — topo\n2. Frase de convite de segunda-feira — destaque médio\n3. 3 diferenciais com ícones em lista\n4. CTA de aula experimental — base"}]},"ac26":{"time":"20h","texto":"Segunda-feira começou com tudo por aqui! 🧡\n\nMesmo com frio e chuva, todos comprometidos!\n\nAdoramos ver tanta gente decidindo cuidar de si mesma logo no início da semana.\n\nSe você ainda não começou, ainda dá tempo. A semana é longa! 💛\n\nBoa noite, Turvo!\n","title":"Bastidores — Segunda de academia cheia","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização / Bastidores\nObjetivo: Mostrar movimento e vitalidade da academia no início da semana, reforçando senso de comunidade ativa e abrindo espaço para quem ainda não começou.\nFunil: Meio — fidelização e prova social indireta de movimento\nAção esperada: Resposta ao story, interesse de quem ainda não é aluno"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMostrar vitalidade e movimento da academia logo na segunda-feira, com tom convidativo para quem ainda não decidiu começar.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia (Academia23.jpg) com sensação de movimento\n• Overlay mínimo — autenticidade prevalece\n• Iluminação quente de fim de tarde\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji e detalhe pontual\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. Tom caloroso e convidativo de início de semana."}]},"ac27":{"time":"08h","texto":"Consistência vence intensidade. Sempre. 💪\n\nNão é quem treina mais pesado uma vez que ganha — é quem aparece toda semana, mesmo nos dias difíceis.\n\nNossas alunas são prova disso. Resultado é feito de constância, não de perfeição.\n\nJá decidiu aparecer essa semana? Manda mensagem! 👇\n📲 (42) 99922-2857\n","title":"Prova Social — Resultado vem de quem não falta","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social / Mentalidade de Constância\nObjetivo: Reforçar que resultado vem da consistência e não de esforços pontuais intensos, gerando identificação com quem já é aluno e atraindo quem busca mudança real e sustentável.\nFunil: Topo/Meio — construção de confiança e autoridade comportamental\nAção esperada: Comentário, identificação, DM solicitando informações"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMulher comum em momento de satisfação simples pós-treino, comunicando mentalidade de constância — não de superação atlética pontual.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: mulher sorrindo de forma natural e relaxada\n• Expressão: satisfação tranquila, sem exagero\n• Ambiente: academia pequena e acolhedora\n• Ângulo: plano médio, câmera na altura dos olhos\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista com luz natural quente. Autenticidade acima de produção excessiva."}]},"ac28":{"time":"12h","texto":"Treino bom começa na noite anterior. 😴\n\nDormir mal afeta diretamente:\n\n✅ Força e disposição no treino\n✅ Recuperação muscular\n✅ Controle de apetite e humor\n\nMeta simples: 7 a 8 horas de sono por noite, sempre que possível.\n\nCuidar do sono é cuidar do resultado. 💛","title":"Dica de Saúde — Sono de qualidade rende mais no treino","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Conteúdo Educativo\nObjetivo: Entregar dica prática sobre sono e recuperação, reforçando que resultados dependem de hábitos além do treino em si.\nFunil: Topo — autoridade e construção de confiança\nAção esperada: Salvamento do story, aplicação prática da dica"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDica prática sobre sono e recuperação muscular, com meta concreta (7-8 horas) — simples de lembrar e aplicar no dia a dia.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: foto da academia com overlay translúcido\n• Elemento central: ícone estilizado de lua ou zZz, em destaque\n• Lista de 3 benefícios com checkmarks em laranja\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — ícone e checkmarks\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nEducativo, limpo, fácil leitura rápida típica de story."}]},"ac29":{"time":"17h","texto":"Aqui ninguém é só mais um número de matrícula. 💛\n\nNa Planeta Corpo, cada professor acompanha de perto sua evolução — sabe seu nome, sua história, seus objetivos.\n\nIsso faz toda diferença na hora de manter a motivação e ver resultado de verdade.\n\nQuer esse tipo de acompanhamento? Aula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#fitness #academia #musculação #saudeebemestar #planetacorpoclubmais ","title":"Diferencial — Atendimento que conhece seu nome","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional, foco em acolhimento humano"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Diferencial Competitivo / Atendimento Personalizado\nObjetivo: Comunicar o diferencial de atendimento próximo e humanizado, contrastando com academias grandes e impessoais — relevante para o público que busca acompanhamento real.\nFunil: Meio — diferenciação frente à concorrência\nAção esperada: Clique no link da bio, mensagem no WhatsApp"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nComunicar o atendimento próximo e personalizado como diferencial real, em contraste implícito com academias grandes e impessoais — sem citar concorrentes diretamente.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: logo centralizado com ícone de \"conexão humana\" (duas figuras estilizadas conversando)\n• Fundo escuro com textura sutil\n• Frase de destaque sobre acompanhamento personalizado\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — ícones e acentos\n• Branco #ffffff — texto e logo\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — topo\n2. Frase sobre atendimento personalizado — destaque médio\n3. CTA de aula experimental — base"}]},"ac30":{"time":"20h","texto":"Equipamento limpo, espaço organizado, ambiente agradável. 🧡\n\nCuidamos de cada detalhe pra que você só precise se preocupar com o seu treino.\n\nÉ assim que a gente entende cuidado de verdade — nos pequenos detalhes do dia a dia.\n\nBoa noite, Turvo!","title":"Bastidores — Cuidando de cada detalhe do espaço","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, foco em organização e cuidado"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização / Bastidores\nObjetivo: Mostrar o cuidado com limpeza e organização do espaço como parte do compromisso de qualidade, gerando confiança em quem valoriza ambiente bem cuidado.\nFunil: Meio — construção de confiança e diferenciação sutil\nAção esperada: Resposta ao story, percepção de qualidade do espaço"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMostrar bastidores de organização e limpeza do espaço, comunicando cuidado nos detalhes que muitas vezes passam despercebidos mas fazem diferença na experiência do aluno.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia (Academia23.jpg) com foco em organização\n• Overlay mínimo — autenticidade prevalece\n• Iluminação natural do ambiente\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji e detalhe pontual\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. Tom de cuidado genuíno com os detalhes."}]},"ac31":{"time":"07h","texto":"Já estamos na metade da semana e o ânimo continua firme! 💛\n\nEsse é o momento em que muita gente desanima — mas não as nossas alunas. Elas sabem que é exatamente na quarta-feira que se prova o compromisso de verdade.\n\nVocê também pode fazer parte dessa rotina. Manda mensagem! 👇\n📲 (42) 99922-2857\n","title":"Prova Social — Metade da semana, motivação em alta","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social / Motivação de Meio de Semana\nObjetivo: Reconhecer que quarta-feira é o ponto em que muitas pessoas perdem o ânimo, posicionando a manutenção da rotina como prova de compromisso real.\nFunil: Topo — despertar interesse e criar conexão emocional\nAção esperada: Comentário, compartilhamento ou DM solicitando informações"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMulher comum mantendo disposição na metade da semana — reforçando que constância no meio da semana é onde o compromisso real se prova.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: mulher sorrindo de forma natural e disposta\n• Expressão: energia mantida, sem sinais de cansaço excessivo\n• Ambiente: academia pequena e acolhedora\n• Ângulo: plano médio, câmera na altura dos olhos\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista com luz natural quente. Autenticidade acima de produção excessiva."}]},"ac32":{"time":"12h","texto":"5 minutos podem evitar dias de dor. 🧘‍♀️\n\nAlongar antes e depois do treino:\n\n✅ Reduz risco de lesão\n✅ Melhora a flexibilidade\n✅ Acelera a recuperação muscular\n\nNão precisa ser complicado — só precisa ser constante.\n\nPequenos hábitos, grandes resultados. 💛\n","title":"Dica de Saúde — Alongamento de 5 minutos faz diferença","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Conteúdo Educativo\nObjetivo: Entregar dica prática e rápida sobre alongamento, mostrando que pequenos hábitos consistentes geram grande impacto na prevenção de lesões.\nFunil: Topo — autoridade e construção de confiança\nAção esperada: Salvamento do story, aplicação prática da dica"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDica prática e rápida sobre alongamento, com tom acessível — \"5 minutos\" como número fácil de lembrar e aplicar.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: foto da academia com overlay translúcido\n• Elemento central: ícone estilizado de figura alongando, em destaque\n• Lista de 3 benefícios com checkmarks em laranja\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — ícone e checkmarks\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nEducativo, limpo, fácil leitura rápida típica de story."}]},"ac33":{"time":"17h","texto":"Não precisa esperar a segunda-feira que vem pra começar. 💛\n\nQuarta-feira também é um ótimo dia pra decidir cuidar de você. Aliás, qualquer dia é.\n\n✅ Mais de 27 anos cuidando de Turvo\n✅ Equipe 100% CREF\n✅ Estrutura completa e moderna\n✅ Desconto Especial para Casais\nAula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n #musculação #saudeebemestar #planetacorpoclubmais ","title":"Matrícula — Quarta-feira é dia de decidir por você","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA de meio de semana"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Conversão / Chamada para Matrícula\nObjetivo: Quebrar a crença comum de que só dá pra começar \"na segunda que vem\", reforçando que qualquer dia é o dia certo para tomar a decisão.\nFunil: Meio/Fundo — converter interesse em contato\nAção esperada: Clique no link da bio, mensagem no WhatsApp"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost que quebra a objeção comum de \"esperar a próxima segunda\" para começar, reforçando os 3 principais diferenciais e convidando à ação imediata no meio da semana.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: logo no topo, 3 diferenciais com ícones no meio, CTA na base\n• Fundo escuro com textura sutil\n• Ícones minimalistas para cada diferencial\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — fundo principal\n• Laranja #e63900 — destaque e CTA\n• Azul escuro #003f6b — ícones e acentos\n• Branco #ffffff — texto e logo\n\nHIERARQUIA VISUAL:\n1. Logo Planeta Corpo — topo\n2. Frase de quebra de objeção (\"não precisa esperar segunda\") — destaque médio\n3. 3 diferenciais com ícones em lista\n4. CTA de aula experimental — base"}]},"ac34":{"time":"21h","texto":"Olha esse movimento de quarta-feira! 🧡\n\nCada treino aqui é um lembrete de que disciplina não tira folga no meio da semana.\n\nOrgulho de ver tanta gente comprometida com a própria saúde.\n\nBoa noite, Turvo! Te esperamos amanhã! 💛\n","title":"Bastidores — Quarta-feira de muito suor e dedicação","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Autêntico, foto real prevalece"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Humanização / Bastidores\nObjetivo: Mostrar movimento e vitalidade da academia no meio da semana, reforçando que disciplina é mantida mesmo quando o ânimo geral costuma cair.\nFunil: Meio — fidelização e prova social indireta de movimento\nAção esperada: Resposta ao story, identificação com o comprometimento mostrado"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMostrar vitalidade e movimento da academia na quarta-feira, com tom de orgulho e reconhecimento do comprometimento dos alunos no meio da semana.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Foto real da academia (Academia23.jpg) com sensação de movimento\n• Overlay mínimo — autenticidade prevalece\n• Iluminação quente de fim de tarde\n\nPALETA OBRIGATÓRIA:\n• Preto #1a1a1a — overlay mínimo (máx 15%)\n• Laranja #e63900 — emoji e detalhe pontual\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nZero produção excessiva. Tom de orgulho e reconhecimento pelo comprometimento."}]},"ac35":{"time":"07h","texto":"Tem dia que o espelho não mostra.\n\nMas o corpo sabe. A disposição sabe. O sono melhor sabe.\n\nCada treino é um tijolo numa construção que ninguém vê de fora — só quem vive sente.\n\nVocê já notou alguma mudança essa semana? Conta pra gente nos comentários 👇\n📲 (42) 99922-2857\n\n","title":"Prova Social — O progresso que ninguém vê de fora","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: manter elementos entre 150px das bordas superior e inferior\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social\nObjetivo: Reforçar que os benefícios da constância vão além do estético — sono, disposição, humor — gerando identificação com quem já treina e curiosidade em quem ainda não começou.\nFunil: Topo/Meio — manter conexão emocional com a base de seguidores\nAção esperada: Comentário relatando progresso pessoal, engajamento"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nUm momento de introspecção pós-treino — não de euforia, mas de satisfação silenciosa. A pessoa olhando para frente, não para o espelho, sugerindo que o progresso real é sentido, não apenas visto.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: aluno(a) comum, roupa simples de treino, sentado(a) num banco da academia, respirando fundo após o treino\n• Expressão: serenidade, satisfação leve, olhar distante e tranquilo\n• Ambiente: academia com iluminação quente, equipamentos desfocados ao fundo\n• Ângulo: plano médio, levemente lateral, câmera na altura dos olhos\n• Profundidade de campo: rasa — foco total na expressão\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista, luz natural quente, sem filtros pesados. Sensação de autenticidade e calma — o oposto da estética de \"esforço máximo\" tradicional do nicho fitness."}]},"ac36":{"time":"12h","texto":"Beber água não é detalhe. É parte do treino. 💧\n\nPouca hidratação = menos força, mais cansaço, recuperação mais lenta.\n\n✅ Beba água antes, durante e depois do treino\n✅ Garrafinha sempre por perto\n✅ Sede já é sinal de atraso — não espere sentir\n\nPequenos hábitos, grandes resultados. A gente te ajuda a montar a rotina certa.\n","title":"Dica de Saúde — Hidratação também é treino","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Conteúdo Educativo\nObjetivo: Posicionar a academia como referência em orientação correta, gerando valor mesmo para quem não está na academia naquele momento.\nFunil: Topo — autoridade e valor gratuito\nAção esperada: Salvar o story, compartilhar, ou comentar dúvida sobre hidratação"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nCard educativo simples e direto sobre a importância da hidratação durante o treino, com checklist visual de fácil leitura.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: foto da academia desfocada, com overlay escuro para legibilidade\n• Elemento principal: ícone de gota de água grande, estilizado, centralizado no topo\n• Checklist: três itens com ✅, tipografia clara e direta\n• Hierarquia: título grande no topo, checklist no meio, CTA no rodapé\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e ícones\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nClean, educativo, fácil leitura em poucos segundos — típico de story informativo de alta retenção."}]},"ac37":{"time":"17h","texto":"Aqui você não treina sozinho. 🧡\n\nNossa equipe 100% formada em Educação Física acompanha cada aluno de perto — ajusta a carga, corrige a postura, comemora cada evolução com você. E temos a tecnologia exclusiva do GympulsePro\n\nSua saúde em primeiro lugar\n\n✅ Equipe 100% CREF\n✅ Mais de 27 anos cuidando de Turvo\n✅ Acompanhamento individual de evolução\n✅ GympulsePro\n\nAula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#academia #musculação #academiaturvoPR #turvoPR #planetacorpoclubmais ","title":"Diferencial — Equipe que acompanha sua evolução de perto","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional, foco em diferencial competitivo"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Diferencial Competitivo\nObjetivo: Comunicar o acompanhamento próximo da equipe técnica como diferencial frente a academias sem orientação qualificada, sem citar concorrentes diretamente.\nFunil: Meio — construção de confiança e justificativa de escolha\nAção esperada: Clique no link da bio, mensagem perguntando sobre aula experimental"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nComunicar que o acompanhamento técnico próximo é parte estrutural da experiência na academia — não um extra, mas o padrão.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: laranja (#e63900) sólido ou levemente texturizado\n• Logo oficial centralizado na parte superior\n• Lista de diferenciais em destaque, com ícones de check\n• CTA em faixa inferior com contraste forte\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — fundo principal\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — textos de apoio\n• Branco #ffffff — texto principal e ícones\n\nESTILO VISUAL:\nInstitucional, confiável, direto — comunica solidez e profissionalismo sem parecer arrogante."}]},"ac38":{"time":"21h","texto":"21h e a energia continua a mesma do início do dia. 🔥\n\nGente chegando do trabalho, trocando o cansaço por disposição.\n\nÉ isso que a gente ama ver todos os dias.\n\nBora pra mais um treino? Te esperamos! 🧡\n\n#fitness #academia #musculação #turvoPR #planetacorpoclubmais","title":"Bastidores — Academia cheia até o fim do dia","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Bastidores / Humanização\nObjetivo: Mostrar o movimento real da academia no período noturno, reforçando que há energia e estrutura em qualquer horário do dia.\nFunil: Topo — conexão emocional e prova de movimento\nAção esperada: Visualização completa do story, identificação com o horário"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nRegistro real e despretensioso do movimento da academia no horário noturno — mostrar que o ambiente continua ativo e acolhedor até o fim do dia.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Cena: ambiente da academia com alunos treinando, iluminação artificial quente\n• Enquadramento: plano geral mostrando movimento, sem focar em rostos específicos\n• Sensação: energia, acolhimento, rotina viva\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia espontânea, tipo \"registro de bastidores\" — sem produção excessiva. Tom de orgulho e energia pelo movimento constante."}]},"ac39":{"time":"08h","texto":"A semana tá quase no fim, mas o cuidado com você não tira folga. 🧡\n\nQuem mantém a rotina até a sexta colhe o fim de semana com mais disposição — pra aproveitar de verdade, sem aquele cansaço acumulado.\n\nBora fechar a semana com chave de ouro? 💪\n📲 (42) 99922-2857","title":"Prova Social — Sexta-feira também é dia de se cuidar","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Prova Social\nObjetivo: Reforçar a constância até o fim da semana, associando o treino de sexta a um fim de semana mais disposto e aproveitado.\nFunil: Topo — manter engajamento e motivação de fechamento de semana\nAção esperada: Comparecimento ao treino de sexta, engajamento no story"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nMostrar que a constância até a sexta-feira é o que garante um fim de semana mais leve e disposto — o treino de sexta como \"fechamento\" positivo da semana.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Personagem: aluno(a) sorrindo de forma natural, leve sensação de alívio e satisfação\n• Expressão: leveza, antecipação positiva do fim de semana\n• Ambiente: academia com luz quente de fim de tarde/manhã\n• Ângulo: plano médio, câmera na altura dos olhos\n• Profundidade de campo: rasa — foco na expressão\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia realista, leve e descontraída — tom de \"sexta-feira boa\", sem perder a autenticidade do dia a dia."}]},"ac40":{"time":"12h","texto":"Fim de semana chegando e a dúvida de sempre: \"posso descansar?\" Pode — e deve. 😌\n\nO músculo cresce no descanso, não só no treino.\n\n✅ 1 a 2 dias de descanso por semana é o ideal\n✅ Sono de qualidade acelera a recuperação\n✅ Descansar não é fraqueza, é estratégia\n\nAproveite o fim de semana com consciência — e volte com tudo na próxima semana!","title":"Dica de Saúde — Descansar também é treinar","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Conteúdo Educativo\nObjetivo: Validar o descanso de fim de semana como parte do processo de treino, gerando autoridade e tranquilidade no aluno.\nFunil: Topo — valor educativo e conexão antes do fim de semana\nAção esperada: Salvar o story, compartilhar, comentar sobre rotina de descanso"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nCard educativo validando o descanso como parte estratégica do treino, com checklist visual simples, no tom certo para fechar a semana sem culpa.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: foto da academia desfocada, overlay escuro para legibilidade\n• Elemento principal: ícone de \"zzz\" ou lua estilizada, centralizado no topo\n• Checklist: três itens com ✅, tipografia clara\n• Hierarquia: título no topo, checklist no meio, CTA no rodapé\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e ícones\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay e fundo\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nClean, tranquilo, tom de \"permissão consciente\" para descansar — reforça autoridade técnica da equipe."}]},"ac41":{"time":"17h","texto":"Que tal já garantir sua vaga e não perder o desconto do mês do casal? 🧡\n\nSem multas absurdas, sem complicação — só você decidindo cuidar de você.\n\n✅ Mais de 27 anos cuidando de Turvo\n✅ Equipe 100% CREF\n✅ Estrutura completa e moderna\n\nAula experimental GRÁTIS — link na bio! 💪\n\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#academia #turvoPR #planetacorpoclubmais","title":"Matrícula — Comece a próxima semana já matriculado","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional com CTA de conversão de fim de semana"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Conversão / Matrícula\nObjetivo: Aproveitar o fechamento da semana para gerar decisão de matrícula antes do fim de semana, posicionando a próxima segunda-feira como ponto de partida.\nFunil: Fundo — conversão direta\nAção esperada: Clique no link da bio, mensagem solicitando aula experimental ou matrícula"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nUsar o fechamento da semana como gatilho de decisão — \"comece a próxima semana já matriculado\" em vez de deixar para depois.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: laranja (#e63900) sólido\n• Logo oficial centralizado na parte superior\n• Lista de diferenciais em destaque, com ícones de check\n• CTA em faixa inferior com contraste forte\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — fundo principal\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — textos de apoio\n• Branco #ffffff — texto principal e ícones\n\nESTILO VISUAL:\nInstitucional, direto, com leve senso de oportunidade — sem parecer promoção agressiva."}]},"ac45":{"time":"10h","texto":"Domingo é dia de recarregar. 🧡\n\nO corpo não cresce durante o treino — ele cresce no descanso. É no dia de folga que o músculo se recupera e fica mais forte.\n\nEntão se hoje é seu dia de descanso, aproveita sem culpa. Segunda a gente volta com tudo. 💪","title":"Dica de Saúde — Descanso também é treino","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Educação\nObjetivo: Entregar valor educativo sobre a importância do descanso na recuperação muscular, posicionando a academia como fonte de orientação confiável mesmo no dia de folga.\nFunil: Topo — autoridade e relacionamento\nAção esperada: Visualização completa, resposta com emoji, salvamento mental da dica"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDomingo como dia legítimo de recuperação — o descanso como parte do processo de evolução, não como preguiça.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Cena: ambiente tranquilo, iluminação suave de domingo\n• Enquadramento: plano geral calmo, sem movimento intenso\n• Sensação: leveza, permissão para descansar, bem-estar\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #003f6b — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia serena, tom acolhedor — clima de domingo tranquilo. Reforça autoridade técnica sem peso. Sem texto na imagem."}]},"ac46":{"time":"07h","texto":"Motivação vem e vai. Hábito fica. 🧡\n\nSe você só treina nos dias que \"está com vontade\", a segunda-feira vai continuar sendo a vilã da sua semana.\n\nO segredo de quem é constante não é força de vontade — é transformar o treino em parte do dia, igual escovar os dentes.\n\nVem treinar com a gente hoje, mesmo sem vontade. Sua versão de quinta-feira agradece. 💪","title":"Dica de Saúde — Segunda não precisa de motivação, precisa de hábito","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Dica de Saúde / Autoridade\nObjetivo: Desconstruir a crença de que motivação é pré-requisito pra treinar, reposicionando hábito como o real motor de consistência — gera identificação forte logo na segunda-feira.\nFunil: Topo — autoridade e conexão emocional\nAção esperada: Resposta com emoji, envio em DM pra alguém que \"também não tem vontade hoje\""},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nContraponto entre motivação (instável) e hábito (constante) — a segunda-feira como prova real desse conceito.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Cena: ambiente da academia em movimento leve de início de semana\n• Enquadramento: plano médio, energia tranquila mas ativa\n• Sensação: acolhimento, \"vem como você está\"\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #00b4b4 — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia real, tom motivacional sem clichê. Sem texto na imagem."}]},"ac49":{"time":"15h","texto":"Toda segunda você promete \"semana que vem eu começo\". E toda semana que vem chega igual. 🧡\n\nQue tal hoje ser diferente? Sua aula experimental é gratuita, sem compromisso — só pra você sentir como é treinar aqui.\n\nChama no WhatsApp e marca o seu horário agora. 💪\n📲 (42) 99922-2857\n📍 Av. Maria Bettega, 360 — Turvo/PR","title":"Matrícula — Comece essa semana, não a próxima","format":"Story","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nDuração recomendada: 7 segundos"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Convite Direto / Matrícula\nObjetivo: Romper o ciclo de procrastinação típico de segunda-feira com CTA direto e de baixo risco (aula experimental grátis), convertendo intenção em ação imediata.\nFunil: Fundo — conversão direta\nAção esperada: Mensagem no WhatsApp agendando aula experimental"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nQuebrar o padrão \"começo segunda que vem\" com humor leve e empatia, oferecendo o caminho de menor fricção: aula experimental grátis, hoje.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Cena: ambiente convidativo da academia, sem intimidação\n• Enquadramento: plano aberto e acolhedor\n• Sensação: \"esse lugar é pra mim\"\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque e CTA\n• Teal #00b4b4 — acento secundário\n• Preto #1a1a1a — overlay\n• Branco #ffffff — texto principal\n\nESTILO VISUAL:\nFotografia real e convidativa. Sem texto na imagem."}]},"ac52":{"time":"17h","texto":"Mais um mês fechado. 🧡\n\nEnquanto isso, tem academia que nem sabe quantos alunos tem matriculados. Aqui a gente sabe o nome, a história e o progresso de cada um.\n\n✅ Equipe 100% CREF\n✅ Mais de 27 anos cuidando de Turvo\n✅ Aproveite o último dia da Promoção \"Mês dos Namorados\"\n✅ Desconto Especial para casais \"Até 50% off\"\n\nJulho começa amanhã. Que comece com você matriculado(a). Aula experimental GRÁTIS — link na bio! 💪\n📍 Av. Maria Bettega, 360 — Centro, Turvo/PR\n📲 (42) 99922-2857\n\n#academiaemturvo #planetacorpoclubmais #treinoturvo #turvopr #qualidadedevida","title":"Diferencial — Fechamos junho com a equipe que te conhece pelo nome","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem de segurança: 80px em todas as bordas\nEstilo: Institucional, virada de mês"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Diferencial Competitivo + Conversão de virada de mês\nObjetivo: Usar o fechamento de junho como gatilho simbólico de novo começo, reforçando o diferencial de acompanhamento nominal e individual frente a academias \"de massa\", sem citar concorrentes.\nFunil: Meio/Fundo — confiança + conversão na virada de mês\nAção esperada: Clique no link da bio, mensagem perguntando sobre matrícula para julho"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nA virada de mês como gatilho simbólico universal de \"novo começo\" — aproveitar esse momento psicológico natural para conversão, ancorado no diferencial de acompanhamento individual.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: laranja (#e63900) institucional\n• Logo oficial centralizado\n• Lista de diferenciais com ícones de check\n• Faixa de CTA com contraste forte\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — fundo principal\n• Teal #00b4b4 — acento secundário\n• Preto #1a1a1a — textos de apoio\n• Branco #ffffff — texto principal e ícones\n\nESTILO VISUAL:\nInstitucional, confiável, tom de virada/novo começo. Sem texto na imagem além dos ícones de check."}]},"ac64":{"time":"10","texto":"Tem aluno que entrou sozinho e hoje treina rodeado de gente que conheceu aqui dentro. 🧡\n\nO Mês do Amigo é sobre isso: usar o pretexto do desconto pra trazer quem você gosta pra essa comunidade.\n\nDaqui um tempo, vocês vão lembrar que tudo começou com uma indicação. Traga o seu! 💪\n📲 (42) 99922-2857\n\n#mesdoamigo #amigoquetreinajunto #planetacorpoclubmais #turvopr #comunidadequemotiva","title":"Seus amigos viram parte da família aqui","format":"Post","secoes":[{"cor":"#e63900","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1350px (proporção 4:5, retrato)\nResolução: 72 DPI\nMargem de segurança: 80px nas bordas\nEstilo: Emocional, comunidade"},{"cor":"#f5a623","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Construção de Marca / Campanha\nObjetivo: Elevar a campanha de \"desconto\" para \"comunidade\", aprofundando a conexão emocional com o motivo real de indicar um amigo.\nFunil: Topo/Meio — relacionamento e consideração\nAção esperada: Comentário emocionado, indicação de amigo, clique no link da bio"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nTirar o foco do desconto e colocar no vínculo humano que a campanha cria, com narrativa de pertencimento.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Grupo real de alunos treinando junto, clima caloroso\n\nPALETA OBRIGATÓRIA:\n• Laranja #e63900 — destaque\n• Preto #1a1a1a — fundo\n• Branco #ffffff — texto\n\nESTILO VISUAL:\nFotografia real e calorosa. Sem texto na imagem."}]},"gy11":{"time":"10h","texto":"Academia Planeta Corpo: 415 alunos cadastrados, mais de 400 aulas realizadas com o GympulsePro. 📈\n\nNão é teoria. É gamificação funcionando todos os dias numa academia real, com alunos reais batendo metas reais.\n\n✅ Frequência consistente\n✅ Comunidade engajada\n✅ Alunos competindo por rankings\n\nVocê quer esse resultado na sua academia? 🎯\n\nDemo gratuita — manda mensagem! 👇\n\n#gympulsepro #gamificacaofitness #treinomotivacao","title":"Case Study — Academia Planeta Corpo","format":"Post","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem: 80px nas bordas\nEstilo: Case study com dados reais"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Case Study / Prova Social B2B\nObjetivo: Usar números reais e verificáveis da Academia Planeta Corpo como prova irrefutável de funcionamento.\nFunil: Meio/Fundo — validação e conversão direta\nAção esperada: DM solicitando demo gratuita"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nApresentar números reais de uma academia cliente como prova irrefutável — números são mais convincentes que adjetivos.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: preto (#0d0d0d) com textura tech sutil\n• Elemento central: números \"215\" e \"400+\" em destaque amarelo (#f5c200)\n• Screenshot do GympulsePro (Drive) abaixo dos números — prova visual\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo total\n• Amarelo #f5c200 — números em destaque e CTA\n• Cinza escuro #1c1c1c — elementos de apoio\n• Branco #ffffff — texto explicativo\n\nESTILO VISUAL:\nDashboard de resultados, profissional e direto."}]},"gy13":{"time":"10h","texto":"Sábado é um ótimo dia pra planejar melhorias na sua academia pra próxima semana. 📋\n\nEnquanto o movimento é mais tranquilo, é hora de pensar: seus alunos estão realmente engajados ou só \"aparecendo\"?\n\nA diferença entre retenção e abandono geralmente está na experiência que você oferece além do equipamento.\n\nVamos conversar sobre isso? Demo gratuita — link na bio 🚀\n\n#gympulsepro #gamificacaoacademia #academiagamificada","title":"Tendência — Fim de semana é hora de planejar","format":"Post","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem: 80px nas bordas\nEstilo: Reflexivo, tom de planejamento de fim de semana"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Reflexão / Convite à Ação\nObjetivo: Aproveitar o momento de menor movimento de sábado (típico do público B2B) para gerar reflexão estratégica sobre retenção, posicionando-se como parceiro de melhoria contínua.\nFunil: Topo/Meio — reflexão estratégica e geração de interesse em conversar\nAção esperada: Salvamento para reflexão posterior, DM com dúvidas"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nPost reflexivo de sábado convidando o gestor a pensar estrategicamente sobre retenção, em vez de apenas vender o produto diretamente — tom mais consultivo, adequado ao ritmo mais lento de fim de semana B2B.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: preto (#0d0d0d) com elemento de calendário ou check-list estilizado\n• Elemento central: ícone de lupa ou pergunta em amarelo (#f5c200), representando reflexão/análise\n• Screenshot do GympulsePro (Drive) como prova de solução disponível\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo principal\n• Amarelo #f5c200 — ícone central e destaques\n• Cinza escuro #1c1c1c — elementos secundários\n• Branco #ffffff — texto explicativo\n\nESTILO VISUAL:\nTom mais calmo e reflexivo que os posts de meio de semana, adequado ao ritmo de sábado."}]},"gy14":{"time":"17h","texto":"Curiosidade de sábado: academias com gamificação têm 30% mais frequência nos fins de semana. 📊\n\nPor quê? Porque alunos engajados não veem o fim de semana como desculpa pra pausar — veem como oportunidade de subir no ranking enquanto os outros descansam. 😏\n\nInteressante, né? Comenta aí o que achou! 👇","title":"Curiosidade — Dado de retenção no fim de semana","format":"Story","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Story Instagram\nDimensões: 1080 × 1920px (proporção 9:16)\nResolução: 72 DPI\nZona segura: 150px das bordas\nEstilo: Curiosidade leve, tom de sábado mais descontraído"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Curiosidade / Dado Interessante\nObjetivo: Engajar com tom mais leve e descontraído de sábado, trazendo dado curioso sobre comportamento competitivo em fins de semana gamificados.\nFunil: Topo — engajamento leve e compartilhável\nAção esperada: Comentário, compartilhamento, curtida"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nDado curioso apresentado com tom leve e levemente bem-humorado, adequado ao clima mais relaxado de sábado, sobre como gamificação afeta comportamento em fins de semana.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Fundo: preto (#0d0d0d) com grade digital sutil\n• Elemento central: número \"30%\" em destaque amarelo (#f5c200) com ícone de calendário de fim de semana\n• Elemento secundário: pequeno ícone de troféu ou medalha sugerindo competição saudável\n\nPALETA OBRIGATÓRIA:\n• Preto #0d0d0d — fundo principal\n• Amarelo #f5c200 — número e destaques\n• Cinza escuro #1c1c1c — elementos secundários\n• Branco #ffffff — texto explicativo\n\nESTILO VISUAL:\nTom mais leve e divertido que os posts de meio de semana, mantendo a estética dark tech."}]},"gy15":{"time":"10h","texto":"Academia que aplicou gamificação viu a frequência dos alunos subir mensuravelmente em 60 dias. 📈\n\nNão é mágica — é comportamento humano respondendo a recompensa visível e progresso mensurável.\n\nAluno que vê seu progresso treina mais. Aluno que treina mais, fica mais tempo.\n\nQuer ver isso na sua academia? Demo gratuita — link na bio 🚀\n\n#gympulsepro #gamificacaofitness #academiagamificada #fittech #rankingacademia","title":"Resultado — Frequência maior em 60 dias","format":"Post","secoes":[{"cor":"#f5c200","num":"01","titulo":"FORMATO E ESPECIFICAÇÕES","conteudo":"Tipo: Post Feed Instagram\nDimensões: 1080 × 1080px (proporção 1:1)\nResolução: 72 DPI\nMargem: 80px nas bordas\nEstilo: SaaS premium, tech, orientado a dados"},{"cor":"#ffffff","num":"02","titulo":"INTENÇÃO DA POSTAGEM","conteudo":"Tipo: Resultado / Case de Sucesso\nObjetivo: Abrir a semana com prova concreta de resultado mensurável, usando dado de aumento de frequência para gerar credibilidade e interesse imediato do gestor.\nFunil: Meio/Fundo — prova de ROI e geração de interesse qualificado\nAção esperada: Clique no link da bio, DM solicitando demo"},{"cor":"#4ade80","num":"03","titulo":"BRIEFING CRIATIVO DETALHADO","conteudo":"CONCEITO CENTRAL:\nAbrir a semana com dado concreto de resultado — frequência mensurável em 60 dias — para captar atenção do gestor de academia com prova, não promessa vaga.\n\nCOMPOSIÇÃO DA IMAGEM:\n• Layout: gráfico estil