insert into public.painel_gilson_state (key, value, updated_at) values ($json$manifest$json$, $json${"so5":{"date":"2026-09-04","time":"09h","format":"Story","caption":"🍦 Bom dia, Turvo!\n\nTerça-feira também merece um sorvetinho, né?\n\nHoje em destaque: CHURROS 😍\n\nPassa lá na loja!","profile":"sorveteria"},"ac62":{"id":"ac62","dia":"3","marca":"Academia","status":"pending","horario":"08:00"},"ac63":{"id":"ac63","dia":"3","marca":"Academia","status":"pending","horario":"12:00"},"ac64":{"id":"ac64","dia":"3","marca":"Academia","status":"pending","horario":"17:00"},"ac65":{"id":"ac65","dia":"3","marca":"Academia","status":"pending","horario":"20:00"},"ac66":{"id":"ac66","dia":"4","marca":"Academia","status":"pending","horario":"08:00"},"ac67":{"id":"ac67","dia":"4","marca":"Academia","status":"pending","horario":"20:00"},"gy35":{"id":"gy35","dia":"3","marca":"GympulsePro","status":"pending","horario":"10:00"},"gy36":{"id":"gy36","dia":"3","marca":"GympulsePro","status":"pending","horario":"18:00"},"gy37":{"id":"gy37","dia":"4","marca":"GympulsePro","status":"pending","horario":"10:00"},"gy38":{"id":"gy38","dia":"4","marca":"GympulsePro","status":"pending","horario":"18:00"},"so82":{"id":"so82","dia":"3","marca":"Sorveteria","status":"pending","horario":"09:00"},"so83":{"id":"so83","dia":"3","marca":"Sorveteria","status":"pending","horario":"11:30"},"so84":{"id":"so84","dia":"3","marca":"Sorveteria","status":"pending","horario":"15:00"},"so85":{"id":"so85","dia":"3","marca":"Sorveteria","status":"pending","horario":"19:00"},"so86":{"id":"so86","dia":"4","marca":"Sorveteria","status":"pending","horario":"09:00"},"so87":{"id":"so87","dia":"4","marca":"Sorveteria","status":"pending","horario":"11:30"},"so88":{"id":"so88","dia":"4","marca":"Sorveteria","status":"pending","horario":"15:00"},"so89":{"id":"so89","dia":"4","marca":"Sorveteria","status":"pending","horario":"17:00"},"so90":{"id":"so90","dia":"4","marca":"Sorveteria","status":"pending","horario":"19:00"},"ac_0409_1":{"date":"2026-09-04","time":"07h00","format":"Story","caption":"A aula do Prof. Wellinton tem uma energia que não dá pra explicar, só sentir. 🧡\n\nVem conferir de perto.","profile":"academia"},"ac_0409_2":{"date":"2026-09-04","time":"11h30","format":"Post","caption":"O Tempo de Cuidado pode ser pra você… ou pra alguém que você quer ver se cuidando também. 🧡\n\nUma amiga, a mãe, uma irmã — quem vem à sua cabeça agora?\n\nConta pra gente nos comentários.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #CuidadoQueSeMultiplica","profile":"academia"},"ac_0409_3":{"date":"2026-09-04","time":"17h00","format":"Reel","caption":"Treinar 30 minutos três vezes por semana rende mais, no fim das contas, do que uma maratona de academia uma vez por mês. 🌿\n\nConstância vence intensidade isolada.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_0409_4":{"date":"2026-09-04","time":"20h00","format":"Post","caption":"Muita aluna chega aqui com medo de \"não aguentar\" depois de anos parada — e sai surpresa com o quanto o corpo responde rápido quando tem acompanhamento certo. 🧡\n\nNunca é tarde pra recomeçar.\n\nQuer recomeçar também?\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #Recomeco","profile":"academia"},"ac_0509_1":{"date":"2026-09-05","time":"09h00","format":"Story","caption":"Sábado é um bom dia pra decidir com calma: já escolheu como vai usar seu Tempo de Cuidado em setembro? 🧡\n\nResponde aí no story.","profile":"academia"},"ac_0509_2":{"date":"2026-09-05","time":"15h00","format":"Post","caption":"Prender a respiração no esforço é hábito comum — e que atrapalha o rendimento. 🌿\n\nExpirar na fase de esforço ajuda a manter a força e a estabilidade.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_0609_1":{"date":"2026-09-06","time":"09h00","format":"Story","caption":"Domingo é dia bom pra parar um minuto e pensar: quem tem cuidado de você ultimamente? 🧡\n\nAmanhã a gente conta mais sobre o Tempo de Cuidado.","profile":"academia"},"ac_0709_1":{"date":"2026-09-07","time":"07h00","format":"Story","caption":"Hoje é feriado de Independência — e a academia também tira o dia pra descansar. 🧡\n\nAmanhã voltamos com tudo, no horário de sempre.","profile":"academia"},"ac_0809_1":{"date":"2026-09-08","time":"07h00","format":"Story","caption":"Quem disse que treinar tem que ser sério o tempo todo? 🧡\n\nNossa aula de dança une movimento, música e diversão — sem perder o resultado.\n\nVem dançar com a gente!","profile":"academia"},"ac_0809_2":{"date":"2026-09-08","time":"11h30","format":"Carrossel","caption":"Em setembro, o cuidado se multiplica. 🧡\n\nFechou plano trimestral, semestral ou anual? Você ganha um Tempo de Cuidado — 7, 15 ou 30 dias, pra usar você ou presentear alguém especial.\n\nArrasta pro lado e entende como funciona.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857","profile":"academia"},"ac_0809_3":{"date":"2026-09-08","time":"17h00","format":"Reel","caption":"Sentir dor durante o treino não é \"estar se esforçando\" — é sinal de alerta. 🌿\n\nAjustar a técnica na hora certa evita lesão e rende mais no longo prazo.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_0809_4":{"date":"2026-09-08","time":"20h00","format":"Post","caption":"Muita aluna chega aqui reclamando de noite mal dormida — e depois de um tempo de treino constante, volta a dormir a noite inteira sem acordar. 🧡\n\nO corpo agradece de formas que a gente nem espera.\n\nQuer sentir essa diferença também?\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #Bemestar","profile":"academia"},"ac_0909_1":{"date":"2026-09-09","time":"07h00","format":"Story","caption":"O David corrige cada detalhe da execução antes de deixar aumentar a carga. 🧡\n\nSegurança em primeiro lugar, resultado vem depois.","profile":"academia"},"ac_0909_2":{"date":"2026-09-09","time":"11h30","format":"Post","caption":"Musculação, dança, spinning, funcional, jump, HIIT — tudo incluso numa mensalidade só, sem pagar taxa extra por modalidade. 🧡\n\nLiberdade pra treinar do seu jeito, no seu ritmo.\n\nVenha conhecer.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #MensalidadeUnica","profile":"academia"},"ac_0909_3":{"date":"2026-09-09","time":"17h00","format":"Reel","caption":"Ela decidiu cuidar de si — e ainda usou o benefício pra cuidar de outra pessoa também. 🧡\n\nEsse mês, o cuidado que você escolhe pode chegar em dobro.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #CuidadoQueSeMultiplica","profile":"academia"},"ac_0909_4":{"date":"2026-09-09","time":"20h00","format":"Story","caption":"Fechou o plano anual no cartão? Além do desconto especial, você ganha 1 mês de Tempo de Cuidado e ainda leva um fone Bluetooth de brinde. 🧡\n\nEnquanto durarem os fones.","profile":"academia"},"ac_1009_1":{"date":"2026-09-10","time":"07h00","format":"Story","caption":"Setembro Amarelo. 💛\n\nVocê está bem de verdade — ou só está dando conta?\n\nSe precisar conversar, CVV 188. Atendimento gratuito e sigiloso, 24 horas.","profile":"academia"},"ac_1009_2":{"date":"2026-09-10","time":"11h30","format":"Post","caption":"A Isadora é a primeira pessoa que te recebe aqui — e o primeiro sorriso do dia faz toda diferença. 🧡\n\nÉ esse acolhimento que a gente mantém desde o primeiro dia.\n\nVenha conhecer.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #EquipePlaneta","profile":"academia"},"ac_1009_3":{"date":"2026-09-10","time":"17h00","format":"Reel","caption":"Pular o aquecimento pra \"ganhar tempo\" costuma sair caro depois. 🌿\n\nUns minutos de aquecimento preparam o corpo e evitam lesão boba no meio do treino.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_1009_4":{"date":"2026-09-10","time":"20h00","format":"Story","caption":"Trabalho, casa, filhos — e ainda assim ela encontra um horário pra treinar. 🧡\n\nO Tempo de Cuidado começa com decisões pequenas, todo dia.","profile":"academia"},"ac_1109_1":{"date":"2026-09-11","time":"07h00","format":"Story","caption":"Ainda ficou com dúvida sobre o Tempo de Cuidado? 🧡\n\nDeixa sua pergunta na caixinha que a gente responde por aqui.","profile":"academia"},"ac_1109_2":{"date":"2026-09-11","time":"11h30","format":"Post","caption":"Teve aluna que usou o Tempo de Cuidado pra trazer a própria mãe pra treinar junto. 🧡\n\nCuidado que vira tempo de qualidade em família.\n\nQuer presentear alguém também?\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #CuidadoQueSeMultiplica","profile":"academia"},"ac_1109_3":{"date":"2026-09-11","time":"17h00","format":"Reel","caption":"\"Não tenho tempo pra treinar\" é a desculpa mais comum que a gente ouve. 🧡\n\nMas cuidar de você não precisa de horas — precisa de decisão. A gente ajuda a encaixar no seu dia.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #CuidadoQueSeMultiplica","profile":"academia"},"ac_1109_4":{"date":"2026-09-11","time":"20h00","format":"Story","caption":"Esse aqui é o fone Bluetooth que acompanha o plano anual pago no cartão. 🎧🧡\n\nEnquanto durarem as unidades — e já estão acabando.","profile":"academia"},"ac_1209_1":{"date":"2026-09-12","time":"09h00","format":"Story","caption":"Treinar sábado sem hora marcada, no seu ritmo — isso também é uma forma de se cuidar. 🧡\n\nTe esperamos!","profile":"academia"},"ac_1209_2":{"date":"2026-09-12","time":"15h00","format":"Post","caption":"Sábado de manhã é uma boa hora pra deixar as refeições da semana organizadas. 🌿\n\nComer bem sustenta o resultado do treino tanto quanto a musculação em si.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_1309_1":{"date":"2026-09-13","time":"09h00","format":"Story","caption":"Domingo é dia de recarregar a energia — inclusive pra continuar se cuidando amanhã. 🧡\n\nTe vemos segunda!","profile":"academia"},"ac_1409_1":{"date":"2026-09-14","time":"07h00","format":"Story","caption":"\"Achei que não ia aguentar nem a primeira semana.\" Hoje ela já treina há 8 meses direto. 🧡\n\nO começo é sempre o mais difícil.","profile":"academia"},"ac_1409_2":{"date":"2026-09-14","time":"11h30","format":"Post","caption":"Desde 1998 cuidando da saúde de Turvo — são 27 anos vendo gerações de famílias passarem por aqui. 🧡\n\nTradição que se renova a cada aluna nova.\n\nVenha fazer parte também.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #27Anos","profile":"academia"},"ac_1409_3":{"date":"2026-09-14","time":"17h00","format":"Reel","caption":"Tênis gasto muda o jeito que o pé pisa — e isso pode sobrecarregar joelho e coluna sem você perceber. 🌿\n\nDe tempos em tempos, vale a pena renovar.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_1409_4":{"date":"2026-09-14","time":"20h00","format":"Post","caption":"Bike ligada, música no ponto certo e a energia da sala toda pedalando junto. 🧡\n\nSpinning aqui é resistência com muita disposição.\n\nVenha sentir essa energia.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #Spinning","profile":"academia"},"ac_1509_1":{"date":"2026-09-15","time":"07h00","format":"Story","caption":"Quem fecha o plano anual no cartão esse mês ganha mais do que imagina. 🧡\n\nDaqui a pouco a gente mostra tudo.","profile":"academia"},"ac_1509_2":{"date":"2026-09-15","time":"11h30","format":"Post","caption":"PLANO ANUAL NO CARTÃO 🧡\n\nDesconto especial + 1 mês de Tempo de Cuidado + fone Bluetooth de brinde.\n\nÉ o começo de uma rotina nova, com um empurrão a mais.\n\nVálido durante setembro ou enquanto durarem os fones.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #CuidadoQueSeMultiplica","profile":"academia"},"ac_1509_3":{"date":"2026-09-15","time":"17h00","format":"Reel","caption":"Treinar bem e dormir mal é remar contra a maré. 🌿\n\nO corpo recupera e constrói músculo justamente enquanto você dorme.\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n\n#AcademiaPlanetaCorpo #TurvoPR #DicaDeSaude","profile":"academia"},"ac_1509_4":{"date":"2026-09-15","time":"20h00","format":"Post","caption":"Depois de 4 meses de treino constante, teve aluna que precisou comprar roupa em número menor. 🧡\n\nResultado que aparece devagar, mas aparece.\n\nQuer começar o seu também?\n\n📍 Av. Maria Bettega, 360 - Turvo/PR\n📲 (42) 99922-2857\n\n#AcademiaPlanetaCorpo #TurvoPR #Resultado","profile":"academia"},"gp_0409_1":{"date":"2026-09-04","time":"10h00","format":"Story","caption":"Aula de sexta cheia e o professor ainda assim sabe exatamente quem tá rendendo mais. 📡💓\n\nO Monitor ao Vivo do GympulsePro mostra BPM, calorias e pontos de cada aluno em tempo real, direto na tela.\n\nArrasta pro lado e veja o monitor em ação.\n\n🚀 Conheça em gympulse.pro","profile":"gympulse"},"gp_0409_2":{"date":"2026-09-04","time":"18h00","format":"Post","caption":"Aluno em teste que treina toda semana parece conversão garantida — mas sem alerta automático de quem tá esfriando, o trial expira e ele simplesmente some. 📊⚠️\n\nAcompanhar de perto é o que converte, não só o uso.\n\n🚀 Conheça em gympulse.pro\n\n#gympulsepro #conversao #gestaoacademia","profile":"gympulse"},"gp_0509_1":{"date":"2026-09-05","time":"10h00","format":"Post","caption":"Sábado de aula cheia é sábado de disputa acirrada no topo do ranking. 🏆📊\n\nO módulo de Rankings do GympulsePro atualiza a colocação de cada aluno automaticamente, por pontos, frequência ou desempenho.\n\n🚀 Conheça em gympulse.pro","profile":"gympulse"},"gp_0609_1":{"date":"2026-09-06","time":"11h00","format":"Story","caption":"Domingo é um bom dia pra pensar: quantos alunos em período de teste já sumiram sem ninguém do time perceber a tempo? 🤔📊\n\nTrial sem acompanhamento ativo é conversão perdida em silêncio.","profile":"gympulse"},"gp_0709_1":{"date":"2026-09-07","time":"10h00","format":"Post","caption":"Base de dados organizada é o que sustenta todo o resto do sistema funcionando direito. 🗂️📊\n\nO módulo de Cadastros do GympulsePro centraliza ficha, histórico e evolução de cada aluno num só lugar.\n\n🚀 Conheça em gympulse.pro","profile":"gympulse"},"gp_0709_2":{"date":"2026-09-07","time":"18h00","format":"Post","caption":"Feriado rendeu um tempo livre a mais? Boa hora pra ver com calma como a gestão da sua academia pode ficar mais simples. 🚀📊\n\n15 minutos, sem compromisso.\n\n🔗 Link na bio\n\n#gympulsepro #demogratuita #gestaoacademia","profile":"gympulse"},"gp_0809_1":{"date":"2026-09-08","time":"10h00","format":"Story","caption":"Terça de aula cheia é justamente quando fica mais fácil não perceber quem começou a faltar. 🤖📲\n\nA IA de Engajamento do GympulsePro identifica sozinha o aluno esfriando e sugere a mensagem certa pra reativar.\n\nArrasta pro lado e veja o alerta em ação.\n\n🚀 Conheça em gympulse.pro","profile":"gympulse"},"gp_0809_2":{"date":"2026-09-08","time":"18h00","format":"Story","caption":"215 alunos cadastrados, biometria monitorada aula por aula — não projeção, número real de quem já usa o GympulsePro todo dia. 💪📊\n\nÉ esse tipo de dado que sustenta decisão de gestão.","profile":"gympulse"},"gp_0909_1":{"date":"2026-09-09","time":"10h00","format":"Story","caption":"Meio de semana é quando o desafio em grupo mais precisa de empurrão pra não esfriar. 🏆📊\n\nO módulo de Desafios do GympulsePro mostra o progresso da turma em tempo real, mantendo todo mundo competindo.\n\n🚀 Conheça em gympulse.pro","profile":"gympulse"},"gp_0909_2":{"date":"2026-09-09","time":"18h00","format":"Post","caption":"Academia sem nenhuma competição ativa no sistema tá desperdiçando a parte que mais